// Qwen3.8 vision gates (PLAN 14v) — oracle = mlx-vlm 0.6.14 pinned to mlx
// 0.31.2 (goldens/qwen38-vision, regenerated by
// scripts/oracle/oracle-qwen38-vision.py; .npz/.bin blobs are
// machine-local + regenerable, manifest.json is tracked).
//
// Tier 1 (model-free, always runs when the goldens exist): preprocessor
// bit-exactness (smart_resize + PIL-fixed-point bicubic + normalize +
// patchify vs the oracle pixel grid) and mRoPE position/delta exactness on
// the oracle's expanded input_ids.
//
// Tier 2 (OPT-IN heavy: MLX_BUN_TEST_QWEN38_VISION=1 — loads the bf16 tower
// sidecar, no 27B): tower parity. Bit-exact at 36 and 576 patches; at 2304
// patches ONE bf16-boundary element in block 13 differs (homebrew-libmlxc
// vs pip-mlx builds disagree on an FMA path — same class as the MTP tap
// finding) and amplifies, so that cell gates on relRMSE ≤ 2e-2.
//
// Tier 3 (same opt-in + the 20 GB target): e2e greedy token parity.
// grad-500x300 and grad-768 are TOKEN-EXACT vs the oracle; grad-96 matches
// ≥16 tokens then flips on an accumulated near-tie — mlx-vlm's language
// implementation is INDEPENDENT of mlx-lm (our bit-exact L1 oracle), so a
// composite bit-match target does not exist; step-0 argmax must match.

import { describe, expect, test } from "bun:test";
import { SNAPSHOT_QWEN38, snapshotQwen38Available } from "./paths";

const G = `${import.meta.dir}/../goldens/qwen38-vision`;
const FIX = `${import.meta.dir}/fixtures`;
const haveGoldens = await Bun.file(`${G}/manifest.json`).exists();
const haveBins = await Bun.file(`${G}/grad-96.pixels.f32.bin`).exists();
const optIn = process.env.MLX_BUN_TEST_QWEN38_VISION === "1";
const haveModel = await snapshotQwen38Available();

const NAMES = ["grad-96", "grad-500x300", "grad-768"] as const;

// ONE model + tower per process (a second 27B instance alongside the first
// reproduces the documented Metal-completion-thread failure under memory
// saturation) — every gated describe below shares these lazy singletons.
let _shared: { model: import("../src/model/qwen3_5").Qwen35Model; tower: import("../src/vision/qwen3vl-tower").Qwen3VLVisionTower } | null = null;
async function sharedModel() {
  if (_shared) return _shared;
  const { loadModelConfig } = await import("../src/config");
  const { Weights } = await import("../src/weights");
  const { Qwen35Model } = await import("../src/model/qwen3_5");
  const { Qwen3VLVisionTower } = await import("../src/vision/qwen3vl-tower");
  const { setMemoryLimit } = await import("../src/mlx/ffi");
  setMemoryLimit(23_000_000_000);
  const config = await loadModelConfig(SNAPSHOT_QWEN38);
  _shared = {
    model: new Qwen35Model(await Weights.open(SNAPSHOT_QWEN38), config),
    tower: Qwen3VLVisionTower.load(SNAPSHOT_QWEN38),
  };
  return _shared;
}

describe.skipIf(!haveGoldens)("qwen3.8 vision: model-free gates", async () => {
  if (!haveGoldens) return;
  const manifest = await Bun.file(`${G}/manifest.json`).json();
  const { preprocessQwen3VLImage } = await import("../src/vision/qwen3vl-preprocess");
  const { qwenRopeIndex } = await import("../src/model/qwen3-mrope");

  test.skipIf(!haveBins)("preprocessor is bit-exact vs the oracle pixel grid", async () => {
    for (const name of NAMES) {
      const bytes = new Uint8Array(await Bun.file(`${FIX}/${name}.png`).arrayBuffer());
      const pp = await preprocessQwen3VLImage(bytes);
      const m = manifest.images[name];
      expect([pp.gridThw]).toEqual(m.grid_thw);
      const golden = new Float32Array(await Bun.file(`${G}/${name}.pixels.f32.bin`).arrayBuffer());
      expect(pp.pixelValues.length).toBe(golden.length);
      let maxAbs = 0;
      for (let i = 0; i < golden.length; i++)
        maxAbs = Math.max(maxAbs, Math.abs(pp.pixelValues[i]! - golden[i]!));
      expect(maxAbs).toBe(0);
    }
  });

  test("mRoPE positions + delta are exact on the oracle input_ids", async () => {
    for (const name of NAMES) {
      const bytes = new Uint8Array(await Bun.file(`${FIX}/${name}.png`).arrayBuffer());
      const pp = await preprocessQwen3VLImage(bytes);
      const m = manifest.images[name];
      const st = qwenRopeIndex(m.input_ids, [pp.gridThw], 2, 248056, 248057);
      expect([
        Array.from(st.positions[0]), Array.from(st.positions[1]), Array.from(st.positions[2]),
      ]).toEqual(m.position_ids);
      expect(st.delta).toBe(m.rope_delta);
    }
  });

  test("image-pad expansion matches the oracle token counts", async () => {
    for (const name of NAMES) {
      const m = manifest.images[name];
      const bytes = new Uint8Array(await Bun.file(`${FIX}/${name}.png`).arrayBuffer());
      const pp = await preprocessQwen3VLImage(bytes);
      const oracleImageTokens = m.input_ids.filter((t: number) => t === 248056).length;
      expect(pp.imageTokens).toBe(oracleImageTokens);
    }
  });
});

describe.skipIf(!optIn || !haveModel || !haveBins)(
  "qwen3.8 vision: tower parity (opt-in, sidecar only)", async () => {
  if (!optIn || !haveModel || !haveBins) return;
  const { preprocessQwen3VLImage } = await import("../src/vision/qwen3vl-preprocess");
  const { Dtype } = await import("../src/mlx/ffi");
  const { tower } = await sharedModel();

  test("tower output vs oracle capture", async () => {
    for (const name of NAMES) {
      const bytes = new Uint8Array(await Bun.file(`${FIX}/${name}.png`).arrayBuffer());
      const pp = await preprocessQwen3VLImage(bytes);
      const out = tower.encode(pp);
      const f = out.astype(Dtype.float32);
      const ours = f.toFloat32();
      f.dispose();
      out.dispose();
      const golden = new Float32Array(await Bun.file(`${G}/${name}.hidden.f32.bin`).arrayBuffer());
      let maxAbs = 0, sumSq = 0, sumRef = 0;
      for (let i = 0; i < golden.length; i++) {
        const d = ours[i]! - golden[i]!;
        maxAbs = Math.max(maxAbs, Math.abs(d));
        sumSq += d * d;
        sumRef += golden[i]! * golden[i]!;
      }
      if (name === "grad-768") {
        // Library-binary FMA residual (header comment): calibrated envelope.
        expect(Math.sqrt(sumSq / sumRef)).toBeLessThan(2e-2);
      } else {
        expect(maxAbs).toBe(0); // BIT-EXACT
      }
    }
  }, 600_000);
});

describe.skipIf(!optIn || !haveModel || !haveBins)(
  "qwen3.8 vision: e2e greedy parity (opt-in, loads the 27B)", async () => {
  if (!optIn || !haveModel || !haveBins) return;
  const manifest = await Bun.file(`${G}/manifest.json`).json();
  const { preprocessQwen3VLImage } = await import("../src/vision/qwen3vl-preprocess");
  const { Qwen3VLVisionTower } = await import("../src/vision/qwen3vl-tower");
  const { qwenRopeIndex } = await import("../src/model/qwen3-mrope");
  const { generate } = await import("../src/generate");
  const ops = await import("../src/mlx/ops");
  const { model, tower } = await sharedModel();

  const run = async (name: string): Promise<{ out: number[]; oracle: number[] }> => {
    const m = manifest.images[name];
    const ids: number[] = m.input_ids;
    const bytes = new Uint8Array(await Bun.file(`${FIX}/${name}.png`).arrayBuffer());
    const pp = await preprocessQwen3VLImage(bytes);
    const idsArr = ops.fromInt32(ids, [1, ids.length]);
    const textEmb = model.embed.encode(idsArr);
    idsArr.dispose();
    const H = textEmb.shape[2]!;
    const start = ids.indexOf(248056);
    const feat = tower.encode(pp);
    const feat3 = ops.reshape(feat, [1, pp.imageTokens, H]);
    feat.dispose();
    const pre = textEmb.slice([0, 0, 0], [1, start, H]);
    const post = textEmb.slice([0, start + pp.imageTokens, 0], [1, ids.length, H]);
    const embeds = ops.concatAxis([pre, feat3, post], 1);
    pre.dispose(); post.dispose(); feat3.dispose(); textEmb.dispose();
    model.mrope = qwenRopeIndex(ids, [pp.gridThw], 2, 248056, 248057);
    const out: number[] = [];
    try {
      for await (const t of generate(model, ids, {
        maxTokens: 32, temperature: 0, promptEmbeddings: embeds,
      } as Parameters<typeof generate>[2])) out.push(t.token);
    } finally {
      model.mrope = null;
      embeds.dispose();
    }
    return { out, oracle: m.gen_ids };
  };

  test("grad-500x300 + grad-768: TOKEN-EXACT vs the oracle", async () => {
    for (const name of ["grad-500x300", "grad-768"]) {
      const { out, oracle } = await run(name);
      // Our stream excludes the trailing EOS the oracle records; compare the
      // common prefix over every token we emitted.
      expect(out.length).toBeGreaterThan(0);
      expect(out).toEqual(oracle.slice(0, out.length));
    }
  }, 3_600_000);

  test("grad-96: ≥16-token prefix + step-0 argmax (accumulated-residual tie)", async () => {
    const { out, oracle } = await run("grad-96");
    expect(out[0]).toBe(oracle[0]); // step-0 argmax
    let prefix = 0;
    while (prefix < out.length && out[prefix] === oracle[prefix]) prefix++;
    expect(prefix).toBeGreaterThanOrEqual(16);
  }, 3_600_000);

});

// ---- video (PLAN 14w): frames-pipeline gates --------------------------------
// Frames are the committed sidecar extractions (tests/fixtures/
// qwen38-clip-frames, provenance = tests/fixtures/qwen38-clip.mov via
// lab/spikes/qwen38-video-sidecar) — both stacks consume identical pixels,
// so no video codec enters the comparison. Goldens: clip-manifest.json +
// blobs from scripts/oracle/oracle-qwen38-video.py.

const haveClipGoldens = await Bun.file(`${G}/clip-manifest.json`).exists();
const haveClipBins = await Bun.file(`${G}/clip-pixels.f32.bin`).exists();

async function loadClipFrames() {
  const { decodeImage } = await import("../src/vision/preprocess");
  const frames = [];
  for (let i = 0; ; i++) {
    const f = Bun.file(`${FIX}/qwen38-clip-frames/frame-${String(i).padStart(4, "0")}.png`);
    if (!(await f.exists())) break;
    frames.push(await decodeImage(new Uint8Array(await f.arrayBuffer())));
  }
  return frames;
}

describe.skipIf(!haveClipGoldens || !haveClipBins)("qwen3.8 video: model-free gates", async () => {
  if (!haveClipGoldens || !haveClipBins) return;
  const m = await Bun.file(`${G}/clip-manifest.json`).json();
  const { preprocessQwen3VLVideoFrames } = await import("../src/vision/qwen3vl-preprocess");
  const { qwenRopeIndex } = await import("../src/model/qwen3-mrope");

  test("video preprocessor is bit-exact vs the oracle pixel grid", async () => {
    const pp = preprocessQwen3VLVideoFrames(await loadClipFrames());
    expect(pp.gridThw).toEqual(m.grid_thw);
    const golden = new Float32Array(await Bun.file(`${G}/clip-pixels.f32.bin`).arrayBuffer());
    expect(pp.pixelValues.length).toBe(golden.length);
    let maxAbs = 0;
    for (let i = 0; i < golden.length; i++)
      maxAbs = Math.max(maxAbs, Math.abs(pp.pixelValues[i]! - golden[i]!));
    expect(maxAbs).toBe(0);
  });

  test("video mRoPE positions + delta are exact (per-frame-group grids)", async () => {
    const pp = preprocessQwen3VLVideoFrames(await loadClipFrames());
    // The reference splits video grids per temporal group (t=1 each) —
    // "timestamps are used to separate videos"; the builder feeds the same.
    const [gridT, gh, gw] = pp.gridThw;
    const grids = Array.from({ length: gridT }, () => [1, gh, gw] as [number, number, number]);
    const st = qwenRopeIndex(m.input_ids, grids, 2, 248056, 248057);
    expect([
      Array.from(st.positions[0]), Array.from(st.positions[1]), Array.from(st.positions[2]),
    ]).toEqual(m.position_ids);
    expect(st.delta).toBe(m.rope_delta);
  });
});

describe.skipIf(!optIn || !haveModel || !haveClipBins)(
  "qwen3.8 video: tower + e2e parity (opt-in)", async () => {
  if (!optIn || !haveModel || !haveClipBins) return;
  const m = await Bun.file(`${G}/clip-manifest.json`).json();
  const { preprocessQwen3VLVideoFrames } = await import("../src/vision/qwen3vl-preprocess");
  const { qwenRopeIndex } = await import("../src/model/qwen3-mrope");
  const { Dtype } = await import("../src/mlx/ffi");
  const ops = await import("../src/mlx/ops");

  test("video tower output vs oracle (per-frame-group attention)", async () => {
    const { tower } = await sharedModel();
    const pp = preprocessQwen3VLVideoFrames(await loadClipFrames());
    const out = tower.encode(pp);
    const f = out.astype(Dtype.float32);
    const ours = f.toFloat32();
    f.dispose();
    out.dispose();
    const golden = new Float32Array(await Bun.file(`${G}/clip-hidden.f32.bin`).arrayBuffer());
    let maxAbs = 0, sumSq = 0, sumRef = 0;
    for (let i = 0; i < golden.length; i++) {
      const d = ours[i]! - golden[i]!;
      maxAbs = Math.max(maxAbs, Math.abs(d));
      sumSq += d * d;
      sumRef += golden[i]! * golden[i]!;
    }
    // Same calibration story as images: bit-exact expected at this size;
    // envelope guards the known library-binary FMA class.
    expect(Math.sqrt(sumSq / Math.max(sumRef, 1e-9))).toBeLessThan(2e-2);
    console.log(`[video tower] max|Δ| ${maxAbs.toExponential(2)}`);
  }, 600_000);

  test("video e2e greedy vs oracle trajectory", async () => {
    const { generate } = await import("../src/generate");
    const { model, tower } = await sharedModel();
    const pp = preprocessQwen3VLVideoFrames(await loadClipFrames());
    const ids: number[] = m.input_ids;
    const idsArr = ops.fromInt32(ids, [1, ids.length]);
    const textEmb = model.embed.encode(idsArr);
    idsArr.dispose();
    const H = textEmb.shape[2]!;
    // Per-frame-group format: splice per pad RUN, consecutive runs consume
    // consecutive tower-feature rows; per-group t=1 grids for positions.
    const feat = tower.encode(pp);
    const segments = [];
    let cursor = 0;
    let row = 0;
    for (let i = 0; i < ids.length; ) {
      if (ids[i] === 248057) {
        let j = i;
        while (j < ids.length && ids[j] === 248057) j++;
        if (cursor < i) segments.push(textEmb.slice([0, cursor, 0], [1, i, H]));
        const sl = feat.slice([row, 0], [row + (j - i), H]);
        segments.push(ops.reshape(sl, [1, j - i, H]));
        sl.dispose();
        row += j - i;
        cursor = j;
        i = j;
      } else i++;
    }
    if (cursor < ids.length)
      segments.push(textEmb.slice([0, cursor, 0], [1, ids.length, H]));
    const embeds = ops.concatAxis(segments, 1);
    for (const s of segments) s.dispose();
    feat.dispose();
    textEmb.dispose();
    const [gridT, gh, gw] = pp.gridThw;
    const grids = Array.from({ length: gridT }, () => [1, gh, gw] as [number, number, number]);
    model.mrope = qwenRopeIndex(ids, grids, 2, 248056, 248057);
    const out: number[] = [];
    try {
      for await (const t of generate(model, ids, {
        maxTokens: 24, temperature: 0, promptEmbeddings: embeds,
      } as Parameters<typeof generate>[2])) out.push(t.token);
    } finally {
      model.mrope = null;
      embeds.dispose();
    }
    // Same acceptance shape as images: exact prefix ≥ half the trajectory
    // (accumulated cross-implementation residual can flip a late near-tie),
    // step-0 argmax must match.
    expect(out[0]).toBe(m.gen_ids[0]);
    let prefix = 0;
    while (prefix < out.length && out[prefix] === m.gen_ids[prefix]) prefix++;
    expect(prefix).toBeGreaterThanOrEqual(Math.min(12, m.gen_ids.length));
  }, 3_600_000);
});

// ---- video FILE decode (the shipped sidecar, PLAN 14w productization) ------
// Auto-skips when no extractor resolves (no beside-binary copy, no native
// pack, no swiftc): resolution + dev-compile live in vision/video-frames.ts.

describe("qwen3.8 video: sidecar file decode", async () => {
  const { resolveFrameExtract, extractVideoFrames } =
    await import("../src/vision/video-frames");
  const bin = await resolveFrameExtract();

  test.skipIf(!bin)("fixture clip decodes to the committed frames, pixel-exact", async () => {
    const bytes = new Uint8Array(await Bun.file(`${FIX}/qwen38-clip.mov`).arrayBuffer());
    const frames = await extractVideoFrames(bytes);
    const committed = await loadClipFrames();
    expect(frames.length).toBe(committed.length);
    for (let i = 0; i < frames.length; i++) {
      expect(frames[i]!.width).toBe(committed[i]!.width);
      expect(frames[i]!.height).toBe(committed[i]!.height);
      // H.264 decode is spec-deterministic: the extracted pixels must equal
      // the committed extraction byte-for-byte.
      expect(Buffer.compare(
        Buffer.from(frames[i]!.data), Buffer.from(committed[i]!.data),
      )).toBe(0);
    }
  }, 120_000);

  test.skipIf(!bin || !haveClipGoldens)("decoded clip preprocesses to the golden grid", async () => {
    const m = await Bun.file(`${G}/clip-manifest.json`).json();
    const { preprocessQwen3VLVideoFrames } = await import("../src/vision/qwen3vl-preprocess");
    const bytes = new Uint8Array(await Bun.file(`${FIX}/qwen38-clip.mov`).arrayBuffer());
    const pp = preprocessQwen3VLVideoFrames(await extractVideoFrames(bytes));
    expect(pp.gridThw).toEqual(m.grid_thw);
  }, 120_000);

  test("video content parts extract and rewrite to template form", async () => {
    const { extractVideos } = await import("../src/vision/prompt");
    const clip = Buffer.from(
      new Uint8Array(await Bun.file(`${FIX}/qwen38-clip.mov`).arrayBuffer()),
    );
    const { messages, videos } = await extractVideos([
      {
        role: "user",
        content: [
          { type: "video_url", video_url: { url: `data:video/quicktime;base64,${clip.toString("base64")}` } },
          { type: "video", data: clip.toString("base64") },
          { type: "text", text: "describe both" },
        ],
      } as never,
    ]);
    expect(videos.length).toBe(2);
    expect(videos[0]!.length).toBe(clip.length);
    const parts = (messages[0]!.content as { type: string }[]).map((p) => p.type);
    expect(parts).toEqual(["video", "video", "text"]);
  });
});

// ---- preprocessing arithmetic units (2026-08-18 review fixes) --------------

describe("qwen3.8 vision: python-faithful arithmetic", async () => {
  const { roundHalfEven, pyFixed1, smartResize, preprocessQwen3VLVideoFrames } =
    await import("../src/vision/qwen3vl-preprocess");

  test("smart_resize rounds HALF-TO-EVEN like Python round (80px case)", () => {
    // Math.round(2.5)=3 gave 96; the reference round(2.5)=2 gives 64 —
    // anchored against _smart_resize_image in the pinned venv.
    expect(smartResize(80, 96, 32, 1, 1e9)).toEqual([64, 96]);
    expect(roundHalfEven(2.5)).toBe(2);
    expect(roundHalfEven(3.5)).toBe(4);
    expect(roundHalfEven(2.4)).toBe(2);
    expect(roundHalfEven(2.6)).toBe(3);
  });

  test("pyFixed1 formats exact ties HALF-TO-EVEN like Python %.1f", () => {
    // Timestamp headers: frame-pair averages land on .x25/.x75 exactly.
    expect(pyFixed1(0.25)).toBe("0.2"); // toFixed says "0.3"
    expect(pyFixed1(1.25)).toBe("1.2");
    expect(pyFixed1(0.75)).toBe("0.8");
    expect(pyFixed1(2.5)).toBe("2.5");
    expect(pyFixed1(3.0)).toBe("3.0");
  });

  test("video group timestamps are frame-pair averages with last-repeat padding", () => {
    const frame = { width: 64, height: 64, data: new Uint8Array(64 * 64 * 3) };
    const pp = preprocessQwen3VLVideoFrames([frame, frame, frame], { sampleFps: 2 });
    // times 0, 0.5, 1.0 (+pad 1.0) → groups (0+0.5)/2=0.25, (1.0+1.0)/2=1.0
    expect(pp.groupTimestamps).toEqual([0.25, 1.0]);
  });
});
